after_script:
  - |
    case "$CI_JOB_STATUS" in
      success)  bash scripts/notify.sh "🚀 CD passed for ${CI_COMMIT_SHORT_SHA}" ;;
      canceled) bash scripts/notify.sh "⏹ CD canceled for ${CI_COMMIT_SHORT_SHA}" ;;
      *)        bash scripts/notify.sh "🔥 CD failed for ${CI_COMMIT_SHORT_SHA}: ${CI_PIPELINE_URL}" ;;
    esac
